       font-size: 0.875rem;
       font-weight: 600;
       letter-spacing: 0.04em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3rem);
       line-height: 1.05;
       letter-spacing: -0.04em;
     }

     .meta {
       margin: 0.9rem 0 0;
       color: var(--color-muted-text);
       line-height: 1.6;
     }

     .stats {
       display: grid;
       grid-template-columns: repeat(3, minmax(0, 1fr));
       gap: 0.75rem;
     }

     .stat {
       padding: 0.9rem;
       border-radius: var(--radius-md);
       background: var(--color-surface-muted);
       border: 1px solid #e6ebf4;
     }

     .stat dt {
       color: var(--color-muted-text);
       font-size: 0.875rem;
       margin-bottom: 0.25rem;
     }

     .stat dd {
       margin: 0;
       font-weight: 700;
       font-size: 1rem;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 0.75rem;
     }

     .button {
       appearance: none;
       border: 1px solid transparent;
       border-radius: 999px;
       padding: 0.9rem 1.2rem;
       font-weight: 700;
       cursor: pointer;
       transition: transform 140ms ease, background-color 140ms ease, border-color 140ms ease, color 140ms ease;
     }

     .button:hover {
       transform: translateY(-1px);
     }

     .button:focus-visible {
       outline: 3px solid var(--color-focus);
       outline-offset: 3px;
     }

     .button-primary {
       background: var(--color-text);
       color: #fff;
     }

     .button-primary:hover {
       background: #111827;
     }

     .button-secondary {
       background: transparent;
       border-color: var(--color-border);
       color: var(--color-text);
     }

     .button-secondary:hover {
       background: #eef3fb;
     }

     .trigger {
       background: linear-gradient(180deg, #d94a4a 0%, var(--color-danger) 100%);
       color: #fff;
       box-shadow: 0 10px 24px rgba(201, 42, 42, 0.24);
     }

     .trigger:hover {
       background: linear-gradient(180deg, #e05858 0%, var(--color-danger-strong) 100%);
     }

     dialog {
       width: min(92vw, 520px);
       border: 1px solid var(--color-border);
       border-radius: 28px;
       padding: 0;
       box-shadow: var(--shadow);
       background: var(--color-surface);
       color: var(--color-text);
     }

     dialog::backdrop {
       background: rgba(15, 23, 42, 0.52);
       backdrop-filter: blur(6px);
     }

     .dialog-panel {
       padding: 1.5rem;
     }

     .dialog-title {
       margin: 0;
       font-size: 1.5rem;
       line-height: 1.15;
       letter-spacing: -0.03em;
     }

     .dialog-copy {
       margin: 0.75rem 0 0;
       color: var(--color-muted-text);
       line-height: 1.6;
     }

     .dialog-note {
       margin: 1rem 0 0;
       padding: 0.9rem 1rem;
       border-radius: 14px;
       background: #fff6f6;
       border: 1px solid #f4c9c9;
       color: #7d2020;
       line-height: 1.5;
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       gap: 0.75rem;
       margin-top: 1.5rem;
