     }

     .dialog-title {
       margin: 0;
       font-size: 1.5rem;
       line-height: 1.15;
       letter-spacing: -0.03em;
     }

     .dialog-copy {
       margin: 0.75rem 0 0;
       color: var(--color-muted-text);
       line-height: 1.6;
     }

     .dialog-note {
       margin: 1rem 0 0;
       padding: 0.9rem 1rem;
       border-radius: 14px;
       background: #fff6f6;
       border: 1px solid #f4c9c9;
       color: #7d2020;
       line-height: 1.5;
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       gap: 0.75rem;
       margin-top: 1.5rem;
       flex-wrap: wrap;
     }

     .button-danger {
       background: var(--color-danger);
       color: #fff;
       min-width: 10ch;
     }

     .button-danger:hover {
       background: var(--color-danger-strong);
     }

     @media (max-width: 780px) {
       .preview {
         grid-template-columns: 1fr;
       }

       .stats {
         grid-template-columns: 1fr;
       }
     }

     @media (forced-colors: active) {
       body, dialog, .image-card, .details-card, .stat, .dialog-note {
         forced-color-adjust: auto;
       }

       .button,
       dialog {
         border: 1px solid ButtonBorder;
       }

       .button-primary,
       .trigger,
       .button-danger {
         background: ButtonFace;
         color: ButtonText;
       }

       .button-secondary {
         background: ButtonFace;
         color: ButtonText;
       }

       .skip-link:focus,
       .button:focus-visible {
         outline-color: Highlight;
       }

       dialog::backdrop {
         background: Canvas;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main">Skip to image preview</a>

   <main id="main" tabindex="-1">
     <div class="preview">
       <figure class="image-card">
         <img
           class="preview-image"
           src="data:image/svg+xml;charset=UTF-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 800'%3E%3Cdefs%3E%3ClinearGradient id='a' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop offset='0%25' stop-color='%23dbe8ff'/%3E%3Cstop offset='100%25' stop-color='%23f8fbff'/%3E%3C/linearGradient%3E%3ClinearGradient id='b' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop offset='0%25' stop-color='%2396b8ff'/%3E%3Cstop offset='100%25' stop-color='%234a6fd6'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1200' height='800' fill='url(%23a)'/%3E%3Ccircle cx='960' cy='140' r='72' fill='%23fff0bf'/%3E%3Cpath d='M0 620 L210 430 L370 545 L550 340 L770 510 L920 390 L1200 620 V800 H0Z' fill='%2392a6c8'/%3E%3Cpath d='M0 680 L185 500 L390 620 L560 450 L750 610 L930 520 L1200 700 V800 H0Z' fill='url(%23b)' opacity='.9'/%3E%3Crect x='120' y='120' width='420' height='300' rx='28' fill='%23ffffff' opacity='.8'/%3E%3Cpath d='M176 326h308' stroke='%23182033' stroke-width='18' stroke-linecap='round' opacity='.12'/%3E%3Cpath d='M176 250h240' stroke='%23182033' stroke-width='18' stroke-linecap='round' opacity='.12'/%3E%3Ccircle cx='238' cy='196' r='22' fill='%23c92a2a'/%3E%3C/svg%3E"
           alt="A warm, softly lit desk setup with a camera, notebook, and coffee"
         >
       </figure>

       <section class="details-card" aria-labelledby="page-title">
         <div>
           <p class="eyebrow">Library image</p>
           <h1 id="page-title">Mountain workspace</h1>
           <p class="meta">
             Preview the image before removing it from your library. Deleting will permanently
             remove this file from your saved images.
           </p>
         </div>

         <dl class="stats" aria-label="Image details">
           <div class="stat">
             <dt>Format</dt>
             <dd>JPEG</dd>
           </div>
           <div class="stat">
             <dt>Size</dt>
             <dd>4.2 MB</dd>
           </div>
           <div class="stat">
             <dt>Uploaded</dt>
             <dd>Today</dd>
           </div>
         </dl>

         <div class="actions">
           <button class="button button-secondary" type="button">Keep image</button>
           <button class="button trigger" type="button" aria-controls="delete-dialog">
             Delete image
           </button>
         </div>
       </section>
     </div>
   </main>

   <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description">
     <div class="dialog-panel">
       <h2 class="dialog-title" id="delete-title">Delete this image from your library?</h2>
       <p class="dialog-copy" id="delete-description">
         This will permanently remove the image and its saved metadata.
       </p>
       <p class="dialog-note">
         This action cannot be undone.
       </p>

       <div class="dialog-actions">
         <button class="button button-secondary" type="button" data-close>Cancel</button>
         <button class="button button-danger" type="button" data-confirm>Delete</button>
       </div>
     </div>
   </dialog>

   <script>
     const dialog = document.getElementById('delete-dialog');
     const trigger = document.querySelector('.trigger');
     const closeButton = dialog.querySelector('[data-close]');
     const confirmButton = dialog.querySelector('[data-confirm]');

     const openDialog = () => {
       dialog.showModal();
       closeButton.focus();
     };

     const closeDialog = () => {
       dialog.close();
     };

     trigger.addEventListener('click', openDialog);
     closeButton.addEventListener('click', closeDialog);
     confirmButton.addEventListener('click', closeDialog);

   </script>
 </body>
 </html>

